def choose_move(observation):
    # Defensive defaults
    pos = observation.get("position", {})
    x = pos.get("x", 0)
    y = pos.get("y", 0)

    # Look for resources or objectives
    grid = observation.get("grid", [])
    height = len(grid)
    width = len(grid[0]) if height > 0 else 0

    # Simple local exploration policy that works across modes:
    #  - Prefer moving toward the nearest cell with a positive signal ('resource', 'objective', 'enemy' indicators)
    #  - If none found, move to stay near center of gravity of visible friendly signals, else stay put.
    best_dx, best_dy = 0, 0
    best_score = -10

    # scan a 3x3 neighborhood around current position within bounds
    for dy in (-1, 0, 1):
        for dx in (-1, 0, 1):
            nx = x + dx
            ny = y + dy
            if dx == 0 and dy == 0:
                # allow staying
                pass
            if nx < 0 or ny < 0 or (width > 0 and nx >= width) or (height > 0 and ny >= height):
                continue

            # get signals at this cell
            cell = None
            if grid:
                try:
                    cell = grid[ny][nx]
                except Exception:
                    cell = None

            score = 0
            if isinstance(cell, dict):
                # prioritize resources or objectives
                if cell.get("resource") or cell.get("objective"):
                    score += 5
                if cell.get("enemy"):
                    score += 2
                if cell.get("ally"):
                    score += 1
                if cell.get("danger"):
                    score -= 3
            else:
                # empty or unknown
                score += 0

            # slight bias towards center area of visible map
            if (nx - width/2) ** 2 + (ny - height/2) ** 2 < (x - width/2) ** 2 + (y - height/2) ** 2:
                score += 0.5

            if score > best_score:
                best_score = score
                best_dx, best_dy = dx, dy

    # Bound dx, dy to -1..1 (already)
    return [best_dx, best_dy]

